insert into public.questions
(exam_category, subject, topic, type, difficulty, body, question_data, options, marks_correct, marks_wrong, explanation, concept_group_id, source_type, source_citation, status)
values
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','statement_based','medium','Consider the following statements about the United Nations Framework Convention on Climate Change (UNFCCC):','{"statements": ["It sets legally binding emission-reduction targets for each developed country.", "It was opened for signature at the 1992 Earth Summit in Rio de Janeiro.", "The principle of ''common but differentiated responsibilities and respective capabilities'' is written into it."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 and 2 only", "isCorrect": false}, {"id": "b", "body": "2 and 3 only", "isCorrect": true}, {"id": "c", "body": "1 and 3 only", "isCorrect": false}, {"id": "d", "body": "1, 2 and 3", "isCorrect": false}]'::jsonb,2,0.66,'Statements 2 and 3 are correct. The UNFCCC was adopted in 1992, opened for signature at Rio and entered into force in 1994; Article 3 sets out common but differentiated responsibilities. Statement 1 is wrong: the Convention itself sets only a non-binding aim for developed countries. Binding, country-by-country targets came with the Kyoto Protocol (1997).','env-unfccc-basics','original_pattern_matched','United Nations Framework Convention on Climate Change (1992), Articles 3 and 4.','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','statement_based','medium','Consider the following statements about the fund for responding to loss and damage under the UNFCCC:','{"statements": ["Contributions to it are legally mandatory for all developed countries.", "Agreement to set it up was reached at COP27 in Sharm el-Sheikh in 2022.", "It was operationalised at COP28 in Dubai in 2023.", "The World Bank hosts it, for an interim period, as a financial intermediary fund."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "Only three", "isCorrect": true}, {"id": "d", "body": "All four", "isCorrect": false}]'::jsonb,2,0.66,'Only statements 2, 3 and 4 are correct. COP27 agreed to create the fund, and COP28 adopted the decision that operationalised it, with the World Bank as its interim host and trustee. Statement 1 is wrong: developed countries are ''urged'' to lead in contributing, and others are encouraged to, but contributions are voluntary.','env-loss-damage-fund','original_pattern_matched','UNFCCC decisions 2/CP.27 and 1/CP.28 (Fund for responding to Loss and Damage).','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','statement_based','medium','Consider the following statements about India''s Carbon Credit Trading Scheme, 2023:','{"statements": ["It is a voluntary international market run by the UNFCCC secretariat.", "It was notified under the Energy Conservation Act, 2001.", "The Bureau of Energy Efficiency is its administrator.", "Under its compliance mechanism, obligated entities in energy-intensive sectors are given greenhouse gas emission intensity targets."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "Only three", "isCorrect": true}, {"id": "d", "body": "All four", "isCorrect": false}]'::jsonb,2,0.66,'Only statements 2, 3 and 4 are correct. The scheme was notified by the Ministry of Power in June 2023 under the Energy Conservation Act (as amended in 2022), with the Bureau of Energy Efficiency as administrator. Obligated entities that beat their emission-intensity targets earn carbon credit certificates that others can buy. Statement 1 is wrong: it is India''s domestic carbon market, with a compliance mechanism and a separate offset (voluntary) mechanism.','env-carbon-credit-trading-scheme','original_pattern_matched','Ministry of Power, Carbon Credit Trading Scheme, 2023 (notified 28 June 2023); Bureau of Energy Efficiency, Indian Carbon Market.','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','statement_based','medium','Consider the following statements about the International Solar Alliance (ISA):','{"statements": ["It was launched by India and France at COP21 in Paris in 2015.", "Its membership is limited to countries lying wholly between the Tropic of Cancer and the Tropic of Capricorn.", "Its headquarters are in Gurugram, India."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true, "numbering": "roman"}'::jsonb,'[{"id": "a", "body": "I only", "isCorrect": false}, {"id": "b", "body": "I and III only", "isCorrect": true}, {"id": "c", "body": "II and III only", "isCorrect": false}, {"id": "d", "body": "I, II and III", "isCorrect": false}]'::jsonb,2,0.66,'Statements I and III are correct. The ISA was launched at COP21 and is headquartered in Gurugram. Statement II is wrong: it began with a focus on solar-rich countries between the tropics, but an amendment to its Framework Agreement opened membership to all member states of the United Nations.','env-international-solar-alliance','original_pattern_matched','International Solar Alliance, Framework Agreement (as amended); MEA, International Solar Alliance.','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','statement_based','easy','Consider the following statements about the Kyoto Protocol:','{"statements": ["It was adopted in 1997.", "It set binding emission-reduction targets for developing countries such as India and China."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": true}, {"id": "b", "body": "2 only", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. The Protocol was adopted at COP3 in Kyoto in 1997 and entered into force in 2005. Statement 2 is wrong: binding targets applied only to the developed and transition economies listed in its Annex B; developing countries had none, though they could host Clean Development Mechanism projects.','env-kyoto-protocol-targets','original_pattern_matched','Kyoto Protocol to the UNFCCC (1997), Article 3 and Annex B.','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','statement_based','easy','Consider the following statements:','{"statements": ["The Conference of the Parties (COP) is the supreme decision-making body of the UNFCCC.", "COP30 was held in Belem, Brazil, in 2025."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": false}, {"id": "b", "body": "2 only", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. The COP, which meets every year, is the Convention''s supreme body. COP30 was held in Belem, in the Brazilian Amazon, in November 2025, after COP29 in Baku (2024) and COP28 in Dubai (2023).','env-cop-basics','original_pattern_matched','UNFCCC, Conference of the Parties (COP); UNFCCC, COP30 (Belem, November 2025).','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','statement_based','hard','Consider the following statements about the New Collective Quantified Goal (NCQG) on climate finance:','{"statements": ["It was adopted at COP29 in Baku in 2024.", "Under it, developed countries are to take the lead in mobilising at least USD 300 billion a year for developing countries by 2035.", "It calls on all actors to scale up finance to developing countries to at least USD 1.3 trillion a year by 2035.", "It succeeds the goal of USD 100 billion a year that developed countries first pledged at COP15 in Copenhagen in 2009."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "Only three", "isCorrect": false}, {"id": "d", "body": "All four", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. COP29''s NCQG set a core goal of at least USD 300 billion a year by 2035, led by developed countries, inside a wider call for USD 1.3 trillion a year from all sources. It replaced the USD 100 billion goal pledged at Copenhagen and formalised at Cancun in 2010. India objected to its adoption as too little.','env-ncqg-cop29','original_pattern_matched','UNFCCC decision 1/CMA.6, New collective quantified goal on climate finance (Baku, November 2024).','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','statement_based','hard','Consider the following statements about the Global Stocktake under the Paris Agreement:','{"statements": ["It assesses each country''s compliance individually and imposes penalties on countries that fall short.", "It takes place every five years.", "The first Global Stocktake concluded at COP28 in Dubai in 2023."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 and 2 only", "isCorrect": false}, {"id": "b", "body": "2 and 3 only", "isCorrect": true}, {"id": "c", "body": "1 and 3 only", "isCorrect": false}, {"id": "d", "body": "1, 2 and 3", "isCorrect": false}]'::jsonb,2,0.66,'Statements 2 and 3 are correct. Article 14 provides for a stocktake every five years; the first ended at COP28, whose decision called for ''transitioning away from fossil fuels in energy systems'' and tripling renewable capacity by 2030. Statement 1 is wrong: the stocktake assesses collective progress towards the Agreement''s goals and is non-punitive; its findings are meant to inform countries'' next NDCs.','env-global-stocktake','original_pattern_matched','Paris Agreement, Article 14; UNFCCC decision 1/CMA.5, Outcome of the first global stocktake (Dubai, 2023).','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','mcq','easy','India announced its ''Panchamrit'' climate commitments, including net-zero emissions by 2070, at:','{}'::jsonb,'[{"id": "a", "body": "COP21, Paris", "isCorrect": false}, {"id": "b", "body": "COP24, Katowice", "isCorrect": false}, {"id": "c", "body": "COP27, Sharm el-Sheikh", "isCorrect": false}, {"id": "d", "body": "COP26, Glasgow", "isCorrect": true}]'::jsonb,2,0.66,'The Prime Minister announced the Panchamrit at COP26 in Glasgow in November 2021: 500 GW of non-fossil capacity, 50 per cent of energy needs from renewables, a one-billion-tonne cut in projected emissions and a 45 per cent cut in emission intensity by 2030, and net zero by 2070.','env-panchamrit-cop26','original_pattern_matched','PIB, National Statement by the Prime Minister at COP26, Glasgow (1 November 2021).','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','mcq','medium','India''s ''Green Credit Programme'', notified in 2023, is implemented under which of the following laws?','{}'::jsonb,'[{"id": "a", "body": "Environment (Protection) Act, 1986", "isCorrect": true}, {"id": "b", "body": "Energy Conservation Act, 2001", "isCorrect": false}, {"id": "c", "body": "Forest (Conservation) Act, 1980", "isCorrect": false}, {"id": "d", "body": "Biological Diversity Act, 2002", "isCorrect": false}]'::jsonb,2,0.66,'The Green Credit Rules, 2023 were notified in October 2023 under the Environment (Protection) Act, 1986, to reward voluntary actions such as tree plantation and water conservation with tradeable green credits; the Indian Council of Forestry Research and Education administers it. The carbon market, by contrast, runs under the Energy Conservation Act.','env-green-credit-programme','original_pattern_matched','MoEFCC, Green Credit Rules, 2023 (notified 12 October 2023).','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','match_the_following','easy','Consider the following pairs of UNFCCC Conferences of the Parties and their outcomes:','{"list_1": ["1. COP3, Kyoto", "2. COP13, Bali", "3. COP21, Paris", "4. COP26, Glasgow"], "list_2": ["Kyoto Protocol", "Bali Action Plan", "Paris Agreement", "Glasgow Climate Pact"], "closing": "How many of the pairs given above are correctly matched?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "isCorrect": false}, {"id": "d", "body": "All four pairs", "isCorrect": true}]'::jsonb,2,0.66,'All four pairs are correct. COP3 (1997) adopted the Kyoto Protocol; COP13 (2007) the Bali Action Plan, which launched talks on long-term cooperation; COP21 (2015) the Paris Agreement; and COP26 (2021) the Glasgow Climate Pact, with its call to ''phase down'' unabated coal power.','env-cop-outcomes-pairs','original_pattern_matched','UNFCCC, decisions and outcomes of COP3, COP13, COP21 and COP26.','draft'),
('upsc','Environment & Ecology','Climate Agreements & Carbon Markets','assertion_reason','medium','Consider the following statements:','{"assertion": "Under the Paris Agreement, each country decides for itself how much it will cut its emissions.", "reason": "Nationally determined contributions (NDCs) are prepared by each Party itself, rather than being assigned or negotiated internationally.", "reason_2": "The Paris Agreement requires each Party to communicate an NDC every five years, each reflecting its highest possible ambition.", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement II and Statement III are correct and both of them explain Statement I", "isCorrect": false}, {"id": "b", "body": "Both Statement II and Statement III are correct but only one of them explains Statement I", "isCorrect": true}, {"id": "c", "body": "Only one of the Statements II and III is correct and that explains Statement I", "isCorrect": false}, {"id": "d", "body": "Neither Statement II nor Statement III is correct", "isCorrect": false}]'::jsonb,2,0.66,'Both Statement II and Statement III are correct, but only Statement II explains Statement I. The Agreement''s bottom-up design lets each country set its own contribution, which is why its targets are ''nationally determined''. Statement III is also true (Article 4.3 and 4.9: successive NDCs every five years, each a progression), but it describes the timing and ratchet of the NDCs, not why their level is set nationally.','env-paris-ndc-design','original_pattern_matched','Paris Agreement (2015), Articles 3, 4.2, 4.3 and 4.9.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','With reference to the Wildlife (Protection) Act, 1972, consider the following statements:','{"statements": ["Hunting of wild animals in a Wildlife Sanctuary is allowed with a licence from the District Collector.", "Grazing of livestock is not permitted in a National Park.", "State Governments can declare both National Parks and Wildlife Sanctuaries."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Only statements 2 and 3 are correct. Section 35(7) bars grazing in a National Park, and the State Government declares Sanctuaries (section 18) and National Parks (section 35). Statement 1 is wrong: hunting is prohibited; only the Chief Wild Life Warden can permit the capture or killing of an animal, and only for purposes the Act specifies.','env-np-vs-sanctuary','original_pattern_matched','Wildlife (Protection) Act, 1972, sections 18, 29, 33 and 35.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about biosphere reserves:','{"statements": ["UNESCO''s Man and the Biosphere (MAB) Programme recognises biosphere reserves in its World Network.", "A biosphere reserve has a core zone, a buffer zone and a transition zone, and human settlements are permitted in the transition zone.", "The Nilgiri Biosphere Reserve, India''s first, lies wholly in Tamil Nadu."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 and 2 only", "isCorrect": true}, {"id": "b", "body": "2 and 3 only", "isCorrect": false}, {"id": "c", "body": "1 and 3 only", "isCorrect": false}, {"id": "d", "body": "1, 2 and 3", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. The MAB Programme (1971) recognises biosphere reserves in its World Network; the core is protected, the buffer allows research and limited use, and the transition zone includes settlements and sustainable economic activity. Statement 3 is wrong: the Nilgiri Biosphere Reserve (1986) spans Tamil Nadu, Kerala and Karnataka.','env-biosphere-reserves','original_pattern_matched','UNESCO, Man and the Biosphere Programme and the World Network of Biosphere Reserves; MoEFCC, Biosphere Reserves of India.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about Ramsar sites in India:','{"statements": ["Chilika Lake and Keoladeo National Park were India''s first Ramsar sites.", "Loktak Lake has never been placed on the Montreux Record.", "The Montreux Record lists Ramsar sites where changes in ecological character have occurred, are occurring or are likely to occur."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true, "numbering": "roman"}'::jsonb,'[{"id": "a", "body": "I only", "isCorrect": false}, {"id": "b", "body": "II and III only", "isCorrect": false}, {"id": "c", "body": "I and III only", "isCorrect": true}, {"id": "d", "body": "I, II and III", "isCorrect": false}]'::jsonb,2,0.66,'Statements I and III are correct. Chilika and Keoladeo were designated in 1981, soon after India joined the Convention. Statement II is wrong: Loktak Lake in Manipur was put on the Montreux Record in 1993 and, with Keoladeo, is still on it; Chilika was placed on it and later removed after its restoration.','env-ramsar-montreux-record','original_pattern_matched','Ramsar Convention Secretariat, Montreux Record and Ramsar Sites Information Service (India).','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about the Wild Life (Protection) Amendment Act, 2022:','{"statements": ["It reduced the number of Schedules in the Act from six to four.", "It removed the separate Schedule of vermin species.", "It added a Schedule for specimens listed in the Appendices of CITES.", "It placed all protected plants and animals in a single Schedule."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "Only three", "isCorrect": true}, {"id": "d", "body": "All four", "isCorrect": false}]'::jsonb,2,0.66,'Only statements 1, 2 and 3 are correct. After the amendment, Schedules I and II cover animals (I giving the highest protection), Schedule III covers specified plants and Schedule IV covers CITES-listed specimens, with a new chapter to implement CITES. The vermin Schedule was dropped; the Centre can still declare a species vermin by notification. Statement 4 is wrong: plants and animals are in different Schedules.','env-wpa-2022-schedules','original_pattern_matched','Wild Life (Protection) Amendment Act, 2022; PRS Legislative Research, The Wild Life (Protection) Amendment Bill, 2021.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about Project Cheetah:','{"statements": ["The first cheetahs under the project were brought from Namibia to Kuno National Park in 2022.", "Gandhi Sagar Wildlife Sanctuary in Madhya Pradesh became the project''s second site.", "The cheetahs brought to India belong to the Asiatic subspecies and came from Iran."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Only statements 1 and 2 are correct. Eight cheetahs from Namibia were released in Kuno in September 2022 and twelve from South Africa followed in 2023; in April 2025 cheetahs were moved to Gandhi Sagar Wildlife Sanctuary. Statement 3 is wrong: the animals are African cheetahs -- Iran''s few surviving Asiatic cheetahs were never part of the project.','env-project-cheetah','original_pattern_matched','National Tiger Conservation Authority, Action Plan for Introduction of Cheetah in India (2022); PIB, cheetah release at Gandhi Sagar Wildlife Sanctuary (April 2025).','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','easy','Consider the following statements:','{"statements": ["Project Tiger was launched in 1973.", "India''s first national park was set up in 1936 as Hailey National Park, now Jim Corbett National Park."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": false}, {"id": "b", "body": "2 only", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. Project Tiger began in 1973 with nine tiger reserves. Hailey National Park, set up in the United Provinces in 1936, was renamed Ramganga and then Corbett National Park, after the hunter-naturalist Jim Corbett.','env-project-tiger-corbett','original_pattern_matched','National Tiger Conservation Authority, Project Tiger; Uttarakhand Forest Department, Corbett Tiger Reserve.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','easy','Consider the following statements:','{"statements": ["World Wetlands Day is observed on 2 February.", "The Ramsar Convention on Wetlands was signed at Ramsar in India."], "closing": "Which of the statements given above is/are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "isCorrect": true}, {"id": "b", "body": "2 only", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. World Wetlands Day, 2 February, marks the signing of the Convention in 1971. Statement 2 is wrong: Ramsar is a town on the Caspian Sea coast of Iran.','env-world-wetlands-day','original_pattern_matched','Ramsar Convention Secretariat, World Wetlands Day and the history of the Convention.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','hard','Consider the following statements about tiger conservation in India:','{"statements": ["Tiger reserves are notified by State Governments on the recommendation of the National Tiger Conservation Authority.", "A tiger reserve consists of a core or critical tiger habitat and a buffer or peripheral area.", "The 2022 cycle of the All India Tiger Estimation put India''s tiger population at about 3,682 (mean estimate).", "Madhya Pradesh had the largest number of tigers in the 2022 estimate."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": false}, {"id": "c", "body": "Only three", "isCorrect": false}, {"id": "d", "body": "All four", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. Under section 38V of the Wildlife (Protection) Act, a State notifies a tiger reserve on the NTCA''s recommendation, with an inviolate core and a buffer where people and wildlife coexist. The 2022 estimate (released in 2023) gave a mean of 3,682 tigers, about three-quarters of the world''s wild tigers, with Madhya Pradesh (785) ahead of Karnataka and Uttarakhand.','env-tiger-reserves-estimation','original_pattern_matched','Wildlife (Protection) Act, 1972, section 38V; NTCA and Wildlife Institute of India, Status of Tigers, Co-predators and Prey in India 2022 (2023).','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','hard','Consider the following statements about Biodiversity Heritage Sites:','{"statements": ["They are notified by State Governments under the Biological Diversity Act, 2002.", "Nallur Tamarind Grove in Karnataka was India''s first Biodiversity Heritage Site.", "Notifying an area as a Biodiversity Heritage Site bans all use of it by local communities."], "closing": "How many of the above statements are correct?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Only statements 1 and 2 are correct. Section 37 of the Act lets a State Government, in consultation with local bodies, notify areas of biodiversity importance as Biodiversity Heritage Sites; Nallur Tamarind Grove was the first, in 2007. Statement 3 is wrong: the national guidelines say notification should not restrict the prevailing practices and usages of local communities, other than those they decide on voluntarily.','env-biodiversity-heritage-sites','original_pattern_matched','Biological Diversity Act, 2002, section 37; National Biodiversity Authority, Guidelines for Selection and Management of Biodiversity Heritage Sites.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','mcq','medium','Which one of the following protected areas, known for the greater one-horned rhinoceros, is a UNESCO World Heritage Site?','{}'::jsonb,'[{"id": "a", "body": "Jaldapara National Park", "isCorrect": false}, {"id": "b", "body": "Orang National Park", "isCorrect": false}, {"id": "c", "body": "Dudhwa National Park", "isCorrect": false}, {"id": "d", "body": "Kaziranga National Park", "isCorrect": true}]'::jsonb,2,0.66,'Kaziranga in Assam, home to about two-thirds of the world''s greater one-horned rhinos, was inscribed as a natural World Heritage Site in 1985. Jaldapara (West Bengal), Orang (Assam) and Dudhwa (Uttar Pradesh) also hold rhinos but are not World Heritage Sites.','env-kaziranga-whs','original_pattern_matched','UNESCO World Heritage Centre, Kaziranga National Park (inscribed 1985).','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','mcq','medium','India''s first Marine National Park was established in the:','{}'::jsonb,'[{"id": "a", "body": "Gulf of Kutch", "isCorrect": true}, {"id": "b", "body": "Gulf of Mannar", "isCorrect": false}, {"id": "c", "body": "Andaman Islands (Wandoor)", "isCorrect": false}, {"id": "d", "body": "Malvan coast", "isCorrect": false}]'::jsonb,2,0.66,'The Marine National Park in the Gulf of Kutch, Gujarat, notified in 1982, was India''s first. The Mahatma Gandhi Marine National Park at Wandoor in the Andamans followed in 1983 and the Gulf of Mannar Marine National Park in 1986.','env-first-marine-national-park','original_pattern_matched','Gujarat Forest Department, Marine National Park, Gulf of Kutch; ENVIS Centre on Wildlife and Protected Areas (WII), Marine Protected Areas of India.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','mcq','easy','Silent Valley National Park, the focus of a famous campaign against a hydroelectric project in the 1970s-80s, is in:','{}'::jsonb,'[{"id": "a", "body": "Karnataka", "isCorrect": false}, {"id": "b", "body": "Tamil Nadu", "isCorrect": false}, {"id": "c", "body": "Kerala", "isCorrect": true}, {"id": "d", "body": "Goa", "isCorrect": false}]'::jsonb,2,0.66,'Silent Valley is in Kerala''s Palakkad district, in the Nilgiri Biosphere Reserve. The ''Save Silent Valley'' movement against a proposed dam on the Kunthipuzha river led to the project being dropped and the forest being declared a national park in 1984.','env-silent-valley','original_pattern_matched','Kerala Forest Department, Silent Valley National Park.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','assertion_reason','easy','Consider the following statements:','{"assertion": "The tiger is described as an ''umbrella species''.", "reason": "Protecting the tiger''s large habitat also protects the many other species that share it.", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct and Statement-II explains Statement-I. An umbrella species needs such a large area of habitat that conserving it automatically conserves many other plants and animals -- which is why tiger reserves also protect watersheds, elephants, deer and countless smaller species.','env-tiger-umbrella-species','original_pattern_matched','National Tiger Conservation Authority, Project Tiger; Wildlife Institute of India.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','assertion_reason','medium','Consider the following statements:','{"assertion": "Elephant Reserves in India are notified under the Wildlife (Protection) Act, 1972.", "reason": "Project Elephant was launched in 1992 to protect elephants, their habitats and their corridors.", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "isCorrect": true}]'::jsonb,2,0.66,'Statement-I is incorrect but Statement-II is correct. Elephant Reserves are an administrative designation made by the States under Project Elephant; unlike tiger reserves, they have no separate legal status under the Wildlife (Protection) Act, though they often contain National Parks and Sanctuaries. Project Elephant was launched in 1992.','env-elephant-reserves-status','original_pattern_matched','MoEFCC, Project Elephant (Project Elephant and Tiger Division); Wildlife Institute of India, Right of Passage: Elephant Corridors of India.','draft')
